package android.accessibilityservice;
import android.content.Context; import android.content.Intent; import android.view.accessibility.*; import java.util.*;
public class AccessibilityService extends Context { public static class GestureResultCallback { public void onCompleted(GestureDescription g){} public void onCancelled(GestureDescription g){} } public void onInterrupt(){} public void onDestroy(){} protected void onServiceConnected(){} public boolean onUnbind(Intent i){return false;} public List<AccessibilityWindowInfo> getWindows(){return null;} public AccessibilityNodeInfo getRootInActiveWindow(){return null;} public boolean dispatchGesture(GestureDescription g, GestureResultCallback callback, android.os.Handler h){if(callback!=null)callback.onCompleted(g);return true;} public void onAccessibilityEvent(AccessibilityEvent e){} }
